const lv_image_dsc_t* mobileIconGet(MobileIcon icon) {
    const auto index = static_cast<size_t>(icon);
    return index < sizeof(ICONS) / sizeof(ICONS[0]) ? ICONS[index] : &icon_dsc_0;
}

MobileIcon mobileIconForApp(const char* id) {
    for (const auto& entry : APP_ICONS) {
        if (strcmp(entry.id, id) == 0) {
            return entry.icon;
        }
    }
    return MobileIcon::Hub;
}
